            var cw_tmp_4: u32;
            if ((v_alpha < v_delta)) {
              cw_tmp_4 = v_alpha;
            } else {
              cw_tmp_4 = v_delta;
            }
            v_alpha = (v_alpha - cw_tmp_4);
          }
          if ((v_layer == v_paintedLayer)) {
            v_alpha = v_delta;
          }
          continuing {
            v_record = (v_record + 2u);
          }
        }
      }
